{ private readonly ImmutableArray<ISemanticSourceAdapterV1> _adapters; private readonly SemanticSourcePolicyCatalogV1 _policies=new(); public SemanticSourceAdapterRegistryV1() : this(new ISemanticSourceAdapterV1[]{new EventIdentitySourceAdapterV1(),new EventWindowSourceAdapterV1(),new EventWindowProductionEventIntelligenceAdapterV1(),new EventWindowDocumentaryContractAdapterV1(),new AstronomicalObjectsSourceAdapterV1(),new SecondaryAstronomicalObjectsSourceAdapterV1(),new AngularSeparationSourceAdapterV1(),new AngularSeparationObservationMetadataAdapterV1(),new ObservationDirectionSourceAdapterV1(),new ObservationLocationSourceAdapterV1(),new ObservationConditionsSourceAdapterV1(),new MeteorActivitySourceAdapterV1(),new FullMoonObservationSourceAdapterV1(),new EclipseCircumstancesSourceAdapterV1(),new OccultationContactsSourceAdapterV1(),new SafetyGuidanceEventSourceAdapterV1(),new ObservationEquipmentKnowledgeAdapterV1(),new ObjectKnowledgeSourceAdapterV1(),new DomainScientificKnowledgeSourceAdapterV1(),new CulturalContextSourceAdapterV1(),new CulturalNameContextSourceAdapterV1(),new EditorialContextSourceAdapterV1(),new SafetyGuidanceKnowledgeAdapterV1()}){}
 public SemanticSourceAdapterRegistryV1(IEnumerable<ISemanticSourceAdapterV1> adapters){if(adapters is null)throw new ArgumentNullException(nameof(adapters),"Semantic source adapter collection cannot be null.");_adapters=ValidateAdapters(adapters).ToImmutableArray();Adapters=_adapters;} public IReadOnlyCollection<ISemanticSourceAdapterV1> Adapters{get;} public IReadOnlyCollection<ISemanticSourceAdapterV1> GetAdapters(SemanticCapabilityId id){var requested=CanonicalizeCapabilityId(id);return _adapters.Where(a=>AdapterSupportsCanonicalCapability(a,requested)).ToArray();} public bool TryGetByAdapterId(string id,out ISemanticSourceAdapterV1 adapter){adapter=_adapters.FirstOrDefault(a=>a.AdapterId==id)!;return adapter is not null;} static SemanticCapabilityId CanonicalizeCapabilityId(SemanticCapabilityId id){var value=id.Value;if(string.IsNullOrWhiteSpace(value))throw new ArgumentException("Semantic capability ID must contain a non-empty value.",nameof(id));var normalized=value.Trim();var mapping=LegacySemanticCapabilityMapV1.Entries.FirstOrDefault(e=>e.LegacyTerm.Equals(normalized,StringComparison.OrdinalIgnoreCase));if(mapping?.CanonicalCapabilityId is { } canonical)return canonical;return new SemanticCapabilityId(normalized);} static bool AdapterSupportsCanonicalCapability(ISemanticSourceAdapterV1 adapter,SemanticCapabilityId requested){if(adapter is null)throw new InvalidOperationException("Semantic source adapter registry contains a null adapter entry.");var capability=adapter.SupportedCapabilityId;if(string.IsNullOrWhiteSpace(capability.Value))throw new InvalidOperationException($"Adapter '{AdapterIdForDiagnostics(adapter)}' ({adapter.GetType().FullName}) declares a malformed capability value '{capability.Value ?? "<null>"}'.");var canonical=CanonicalizeCapabilityId(capability);return canonical.Equals(requested);} static IEnumerable<ISemanticSourceAdapterV1> ValidateAdapters(IEnumerable<ISemanticSourceAdapterV1> adapters){var validated=new List<ISemanticSourceAdapterV1>();var ids=new HashSet<string>(StringComparer.Ordinal);var index=0;foreach(var adapter in adapters){if(adapter is null)throw new InvalidOperationException($"Semantic source adapter collection contains a null adapter entry at index {index}.");var type=adapter.GetType().FullName;var adapterId=adapter.AdapterId;if(string.IsNullOrWhiteSpace(adapterId))throw new InvalidOperationException($"Adapter '{type}' has a null or blank AdapterId.");if(string.IsNullOrWhiteSpace(adapter.SourceId))throw new InvalidOperationException($"Adapter '{adapterId}' ({type}) has a null or blank SourceId.");var capability=adapter.SupportedCapabilityId;if(string.IsNullOrWhiteSpace(capability.Value))throw new InvalidOperationException($"Adapter '{adapterId}' ({type}) declares a null or blank capability ID value.");if(!ids.Add(adapterId))throw new InvalidOperationException($"Duplicate semantic source adapter AdapterId '{adapterId}' detected for adapter type '{type}'.");validated.Add(adapter);index++;}return validated;} static string AdapterIdForDiagnostics(ISemanticSourceAdapterV1 adapter)=>string.IsNullOrWhiteSpace(adapter.AdapterId)?"<blank>":adapter.AdapterId; public SemanticSourceAdapterRegistryValidationResultV1 Validate()=>CertifyAgainstPolicies(); public IReadOnlyCollection<SemanticSourceAdapterCoverageItemV1> GetCoverageReport()=>CertifyAgainstPolicies().Coverage; public SemanticSourceAdapterRegistryValidationResultV1 CertifyAgainstPolicies()=>SemanticSourceAdapterCertifierV1.Certify(_adapters,_policies); }
public static class SemanticSourceAdapterCertifierV1
{ public static SemanticSourceAdapterRegistryValidationResultV1 Certify(IReadOnlyCollection<ISemanticSourceAdapterV1> adapters, SemanticSourcePolicyCatalogV1 policies){var errors=new List<string>();var warnings=new List<string>();foreach(var g in adapters.GroupBy(a=>a.AdapterId).Where(g=>g.Count()>1))errors.Add($"Duplicate adapter id '{g.Key}'.");foreach(var a in adapters){if(a.SourceId==SemanticSourcePolicyVocabularyV1.LegacyRawJsonScanner)errors.Add($"Raw JSON adapter is not allowed: {a.AdapterId}.");if(!policies.TryGet(a.SupportedCapabilityId,out var p)){errors.Add($"No policy for {a.AdapterId}.");continue;}var s=p.ApprovedSources.FirstOrDefault(x=>x.SourceId==a.SourceId);if(s is null)errors.Add($"Adapter source not approved: {a.AdapterId}.");else{if(s.EvidenceCategory!=a.EvidenceCategory)errors.Add($"Adapter evidence mismatch: {a.AdapterId}.");if(a.MaximumEvidenceStrength<s.MinimumStrength)errors.Add($"Adapter strength insufficient: {a.AdapterId}.");if(s.EventSpecific!=a.EventSpecific)errors.Add($"Adapter event-specific flag mismatch: {a.AdapterId}.");if(s.CompatibilityOnly)errors.Add($"Compatibility-only adapter cannot certify: {a.AdapterId}.");}}
 var coverage=new List<SemanticSourceAdapterCoverageItemV1>();foreach(var p in policies.Policies.OrderBy(p=>p.SemanticCapabilityId.Value)){foreach(var s in p.ApprovedSources.OrderBy(s=>s.Priority)){var a=adapters.FirstOrDefault(x=>x.SupportedCapabilityId.Equals(p.SemanticCapabilityId)&&x.SourceId==s.SourceId);var status=!s.ActiveInV1?SemanticSourceAdapterCertificationStatusV1.FutureUnavailable:a is null?SemanticSourceAdapterCertificationStatusV1.AdapterMissing:s.CompatibilityOnly?SemanticSourceAdapterCertificationStatusV1.CompatibilityOnly:a.EvidenceCategory!=s.EvidenceCategory?SemanticSourceAdapterCertificationStatusV1.EvidenceMismatch:a.MaximumEvidenceStrength<s.MinimumStrength?SemanticSourceAdapterCertificationStatusV1.InsufficientStrength:SemanticSourceAdapterCertificationStatusV1.AdapterCertified;coverage.Add(new(p.SemanticCapabilityId,s.SourceId,a?.AdapterId,status,a is not null,s.ActiveInV1,a is not null,status==SemanticSourceAdapterCertificationStatusV1.AdapterCertified?"Implemented":"Gap",status.ToString()));}}
 return new(errors.Count==0,errors.ToImmutableArray(),warnings.ToImmutableArray(),coverage.ToImmutableArray());}}
